import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * <p>
 * The original implementation configured the {@link Parser} inside a synchronized block
 * and relied on the parser’s default options.  This allowed the parser to resolve XML
 * entities, exposing the service to XML External Entity (XXE) attacks.  The fix creates a
 * fresh {@link ParserOptions} instance for each request, explicitly disables entity
 * resolution (and DTD support when available), and passes those options to the parser
 * *before* parsing begins.  No synchronization is required because a new {@link Parser}
 * instance is obtained for every call.
 * </p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // ----------------------------------------------------------------------
    //  MessageBodyReader implementation – secure parsing
    // ----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a fresh parser for this request – no shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Build parser options that are safe against XXE.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disable external entity resolution.
        options.setResolveEntities(false);
        // If the underlying implementation supports it, also disable DTD processing.
        // This call is safe – if the method does not exist in the used version,
        // the code will still compile because the method is present in recent
        // Abdera releases.  If it is absent, the line can be removed without
        // affecting the security guarantees provided by setResolveEntities(false).
        try {
            options.setSupportDTD(false);
        } catch (NoSuchMethodError ignored) {
            // Older Abdera versions do not expose setSupportDTD; the previous
            // call to setResolveEntities already prevents DTD/Entity expansion.
        }

        // Parse the input using the securely configured options.
        Document<T> doc;
        try {
            doc = parser.parse(entityStream, options);
        } catch (Exception e) {
            // Wrap any parsing exception as an IOException to satisfy the JAX‑RS contract.
            throw new IOException("Failed to parse Atom XML payload", e);
        }

        // The document root is the requested element type.
        return doc.getRoot();
    }

    // ----------------------------------------------------------------------
    //  Other abstract / concrete methods required by the provider
    // ----------------------------------------------------------------------
    // (omitted for brevity – unchanged from the original source)
}
