     *  This avoids the heavy, complex pattern that could be abused for DoS. */
    private static final String DEFAULT_URL_REGEX =
            "^(https?|ftp)://[^\\s]+$";

    private String urlRegex;
    private String urlRegexExpression;

    // other methods ...

    /**
     * Returns a regular expression used for client‑side URL validation.
     * <p>
     * The method now:
     * <ul>
     *   <li>Handles {@code null} and empty values safely.</li>
     *   <li>Catches any exception thrown by {@code parse(...)} and falls back.</li>
     *   <li>Never returns {@code null}; a predefined safe regex is always supplied.</li>
     * </ul>
     *
     * @return a non‑null regex string suitable for URL validation
     */
    public String getUrlRegex() {
        // 1. Prefer an explicitly supplied expression (may be a SpEL expression)
        if (StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                String parsed = (String) parse(urlRegexExpression, String.class);
                if (StringUtils.isNotBlank(parsed)) {
