        // 2. Fallback to a directly supplied regex string
        if (StringUtils.isNotBlank(urlRegex)) {
            return urlRegex;
        }

        // 3. Final safe default – guarantees a non‑null, lightweight pattern
        return DEFAULT_URL_REGEX;
