import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

/**
 * Utility methods for importing files.
 *
 * The {@code allocateFile} method creates a new {@link File} inside a given
 * directory, ensuring that the supplied {@code name} cannot be used to escape
 * that directory (prevents directory‑traversal attacks).  If a file with the
 * desired name already exists, a numeric suffix is added until a free name
 * is found.
 */
public class ImportingUtilities {

    // other methods ...

    /**
     * Allocates a file inside {@code dir} using {@code name} as the desired
     * filename. The method sanitises {@code name} to prevent path traversal,
     * normalises the resulting path and guarantees that the final file is
     * located within {@code dir}.
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the requested filename (may contain a query part after '?')
     * @return a {@link File} object that does not yet exist on disk
     * @throws IllegalArgumentException if {@code dir} or {@code name} is invalid,
     *                                  or if the resolved path would escape {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // Strip any URL‑style query string (e.g., "file.txt?foo=bar")
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }
        if (name.isEmpty()) {
            throw new IllegalArgumentException("File name must not be empty");
        }

        // Resolve the requested name against the target directory and normalise it.
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the resolved path is still inside the intended directory.
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Invalid file name: path traversal outside the target directory is not allowed");
        }

        // Separate the filename into prefix and suffix (extension) for later
        // generation of a unique name if the file already exists.
        String fileName = targetPath.getFileName().toString();
        int dot = fileName.lastIndexOf('.');
        String prefix = (dot < 0) ? fileName : fileName.substring(0, dot);
        String suffix = (dot < 0) ? "" : fileName.substring(dot);
        int index = 2;
        Path parent = targetPath.getParent();

        // Find a non‑existent file name, appending a numeric suffix when needed.
        while (Files.exists(targetPath)) {
            String newName = prefix + "-" + index++ + suffix;
            targetPath = parent.resolve(newName);
        }

        // Ensure the parent directory hierarchy exists.
        parent.toFile().mkdirs();

        return targetPath.toFile();
    }

    // other methods ...

}
