private void doInclude(HttpServletRequest request, HttpServletResponse response, String resourceUrl) throws ServletException, IOException {
    if (resourceUrl == null) {
        throw new ServletException("resourceUrl must not be null");
    }
    if (this.contentType != null) {
        response.setContentType(this.contentType);
    }

    // Resolve the servlet context base directory once
    File baseDir = new File(request.getServletContext().getRealPath("/")).getCanonicalFile();

    String[] resourceUrls = StringUtils.tokenizeToStringArray(resourceUrl, RESOURCE_URL_DELIMITERS);
    for (String url : resourceUrls) {
        if (!StringUtils.hasText(url)) {
            continue;
        }

        // Basic traversal checks
        if (url.contains("..") || url.contains("\\") || url.startsWith("/")) {
            logger.warn("Blocked attempt to include potentially unsafe resource: [" + url + "]");
            throw new ServletException("Invalid resource path: " + url);
        }

        // Normalise the path to eliminate any remaining ".." segments
        Path normalizedPath = Paths.get(url).normalize();
        String normalized = normalizedPath.toString();

        // Resolve against the base directory and obtain the canonical path
        File targetFile = new File(baseDir, normalized).getCanonicalFile();

        // Ensure the resolved file is still inside the servlet context directory
        if (!targetFile.getPath().startsWith(baseDir.getPath())) {
            logger.warn("Blocked directory‑traversal attempt: [" + url + "]");
            throw new ServletException("Resource path outside allowed directory: " + url);
        }

        // Verify against the configured allowed pattern, if any
        if (this.allowedResources != null && this.pathMatcher != null
                && !this.pathMatcher.match(this.allowedResources, normalized)) {
            throw new ServletException(
                    "Resource [" + normalized + "] does not match allowed pattern [" + this.allowedResources + "]");
        }

        if (logger.isDebugEnabled()) {
            logger.debug("Including resource [" + normalized + "]");
        }

        RequestDispatcher rd = request.getRequestDispatcher(normalized);
        if (rd == null) {
            throw new ServletException("No RequestDispatcher found for resource: " + normalized);
        }
        rd.include(request, response);
    }
}
