private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    Path targetPath = targetDirectory.toPath().toRealPath(LinkOption.NOFOLLOW_LINKS);
    ArchiveEntry entry = supplier.getNextReadableEntry();
    while (entry != null) {
        String entryName = entry.getName();
        if (entryName == null) {
            throw new IOException("Archive entry name is null");
        }
        // Reject absolute paths
        if (entryName.startsWith("/") || entryName.startsWith("\\")) {
            throw new IOException("Invalid entry name: absolute path not allowed: " + entryName);
        }
        // Resolve the entry against the target directory and normalize
        Path entryPath = targetPath.resolve(entryName).normalize();

        // Ensure the resulting path is still inside the target directory
        if (!entryPath.startsWith(targetPath)) {
            throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
        }

        if (entry.isDirectory()) {
            Files.createDirectories(entryPath);
        } else {
            // Ensure parent directory exists
            Path parent = entryPath.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            try (OutputStream out = Files.newOutputStream(entryPath, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
                writer.writeEntryDataTo(entry, out);
            }
        }
        entry = supplier.getNextReadableEntry();
    }
}
