        if (type == null && answer == null) {
            answer = body;
        } else if (answer == null) {
            if (cause != null) {
                throw cause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
            }
        }

        return answer;
    }

    // -------------------------------------------------------------------------
    //  Helper methods – secure XML parsing
    // -------------------------------------------------------------------------

    /**
     * Parses XML from an {@link InputStream} into a {@link Document} using a
     * {@link DocumentBuilderFactory} that has all external entity features disabled.
     */
    private Document parseSecureDocument(InputStream is) throws Exception {
        try (InputStream input = is) {
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            configureSecureFactory(dbf);
            DocumentBuilder db = dbf.newDocumentBuilder();
