import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

/**
 * Helper that decides whether a self‑update request is allowed.
 *
 * <p>
 * The original implementation only compared the e‑mail address from the request
 * with the one stored in the database.  That allowed an attacker to change the
 * e‑mail of another user by simply sending a request that contained the target
 * user’s e‑mail address.  The new implementation enforces strict ownership
 * checks:
 * <ul>
 *   <li>The authenticated principal (obtained from {@code request.getUserPrincipal()})
 *       must be present and must match the user id extracted from the request URL.</li>
 *   <li>Only mutable fields may be changed.  Immutable fields such as primary e‑mail,
 *       user name, origin, verification status and active flag must remain unchanged.</li>
 *   <li>All comparisons are null‑safe using {@link Objects#equals(Object, Object)}.</li>
 * </ul>
 * If any of these conditions fail the method returns {@code false}, otherwise {@code true}.
 * </p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming request is allowed to update the user identified
     * by the path variable.
     *
     * @param request the HTTP request containing the JSON payload and authentication info
     * @return {@code true} if the request is a legitimate self‑update, {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // --------------------------------------------------------------------
        // 1. Verify that the request is authenticated and that the caller is
        //    attempting to modify its own account.
        // --------------------------------------------------------------------
        Principal principal = request.getUserPrincipal();
        if (principal == null) {
            // No authenticated principal – definitely not allowed.
            return false;
        }
        String authenticatedUserId = principal.getName();
        if (authenticatedUserId == null || authenticatedUserId.isEmpty()) {
            return false;
        }

        // Extract the user id from the request URL (e.g. /Users/{id})
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request)
        );

        // The caller must be updating its own record.
        if (!Objects.equals(authenticatedUserId, targetUserId)) {
            return false;
        }

        // --------------------------------------------------------------------
        // 2. Parse the incoming JSON payload.
        // --------------------------------------------------------------------
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);
        if (scimUserFromRequest == null) {
            // Empty or malformed payload – reject.
            return false;
        }

        // --------------------------------------------------------------------
        // 3. Load the persisted user record for comparison.
        // --------------------------------------------------------------------
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot allow an update.
            return false;
        }

        // --------------------------------------------------------------------
        // 4. Enforce immutability of sensitive fields.
        // --------------------------------------------------------------------
        // Primary e‑mail
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        // User name (login)
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        // Origin (external identity provider)
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }
        // Verification flag – only an admin should be able to toggle this.
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        // Active flag – also admin‑only.
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }

        // All immutable checks passed – the request is a legitimate self‑update.
        return true;
    }

    // other methods (unchanged)
}
